n BOA", "duty_rate": "$200,000 a month", "announcement_date": "this spring"}}, {"claim_id": "claim_3efe5110aa884dd444bc8b29", "quote": "new tariffs initiated by the Trump administration this spring have raised the company's costs by more than $200,000 a month", "url": "https://www.ajc.com/business/georgia-auto-sector-fears-tariff-damage/lT9ZkTnli54RJltUfZT2OI", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Trump administration", "duty_rate": "$200,000 a month"}}]}, {"pair_id": "conflict_e38e51722d1667d28d72a766", "claim_ids": ["claim_2640566dc8a526e3a8ecae6f", "claim_cc8a57e441eb6ccfbd108954"], "query_ids": ["q_274"], "claims": [{"claim_id": "claim_2640566dc8a526e3a8ecae6f", "quote": "President Donald Trump signed executive orders placing 25% tariffs on all steel and aluminum imports into the U.S. on Monday.", "url": "https://www.wardsauto.com/news/archive-auto-tariffs-trump-steel-aluminum-automotive/739872", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on all steel and aluminum imports", "legal_authority": "executive orders", "duty_rate": "25%", "announcement_date": "Monday"}}, {"claim_id": "claim_cc8a57e441eb6ccfbd108954", "quote": "Trump said in a proclamation that the tariffs are justified on national security grounds", "url": "https://www.npr.org/2025/03/12/nx-s1-5325933/steel-aluminum-tariffs-autos", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "national security grounds", "announcement_date": "starting today"}}]}]}

